// ── Graph: adjacency list with weighted and directed support ───
class Graph {
  constructor(directed = false) {
    this.adj = new Map();   // vertex → [{to, weight}]
    this.directed = directed;
  }

  addVertex(v) {
    if (!this.adj.has(v)) this.adj.set(v, []);
  }

  addEdge(u, v, weight = 1) {
    this.addVertex(u);
    this.addVertex(v);
    this.adj.get(u).push({ to: v, weight });
    if (!this.directed) this.adj.get(v).push({ to: u, weight });
  }

  degree(v) { return (this.adj.get(v) ?? []).length; }

  neighbours(v) { return (this.adj.get(v) ?? []).map(e => e.to); }
}

// Build the undirected graph:
// A-B(2), A-C(4), B-C(1), B-D(5), C-E(3), D-E(2)
