// ── BFS: shortest hop-count distances from source ─────────────
function bfs(graph, start) {
  const dist = new Map();
  const parent = new Map();
  dist.set(start, 0);
  parent.set(start, null);
  const queue = [start];

  while (queue.length > 0) {
    const u = queue.shift();
    for (const v of graph.neighbours(u)) {
      if (!dist.has(v)) {
        dist.set(v, dist.get(u) + 1);
        parent.set(v, u);
        queue.push(v);
      }
    }
  }
  return { dist, parent };
}

const { dist, parent } = bfs(g, 'A');
console.log('BFS distances from A:');
for (const [v, d] of dist) {
  // Reconstruct path
  const path = [];
  let cur = v;
  while (cur !== null) { path.unshift(cur); cur = parent.get(cur); }
  console.log(`  ${v}: ${d} hops  (${path.join(' → ')})`);
}
// A: 0  (A)
// B: 1  (A → B)
// C: 1  (A → C)
// D: 2  (A → B → D)
// E: 2  (A → C → E)

// ── DFS: all vertices reachable from start ────────────────────
function dfs(graph, start) {
  const visited = new Set();
  const order = [];
  function visit(v) {
    visited.add(v);
    order.push(v);
    for (const u of graph.neighbours(v)) {
      if (!visited.has(u)) visit(u);
    }
  }
  visit(start);
  return order;
}
console.log('DFS order from A:', dfs(g, 'A').join(' → '));
// DFS order from A: A → B → C → E → D  (depends on adj list order)

// ── Euler circuit check + Hamiltonian brute-force (small n) ───

// Euler circuit: all vertices must have even degree
function hasEulerCircuit(graph) {
  for (const [v, _] of graph.adj) {
    if (graph.degree(v) % 2 !== 0) return false;
  }
  return true; // assumes graph is connected
}

// Euler path: exactly 2 odd-degree vertices
function eulerPathInfo(graph) {
  const oddVerts = [...graph.adj.keys()].filter(v => graph.degree(v) % 2 !== 0);
  if (oddVerts.length === 0) return { type: 'circuit', endpoints: null };
  if (oddVerts.length === 2) return { type: 'path', endpoints: oddVerts };
  return { type: 'none', oddCount: oddVerts.length };
}

