// ── Hamiltonian cycle — brute force via permutations (n ≤ 10) ─
function hasHamiltonianCycle(graph) {
  const verts = [...graph.adj.keys()];
  const n = verts.length;
  const start = verts[0];

  // Try all permutations of remaining vertices
  function permute(arr, cur) {
    if (cur.length === n - 1) {
      // Check path: start → ...cur → start
      const full = [start, ...cur];
      for (let i = 0; i < n - 1; i++) {
        const u = full[i], v = full[i + 1];
        if (!graph.neighbours(u).includes(v)) return false;
      }
      // Check closing edge
      return graph.neighbours(full[n - 1]).includes(start);
    }
    for (let i = 0; i < arr.length; i++) {
      const next = arr.filter((_, j) => j !== i);
      if (permute(next, [...cur, arr[i]])) return true;
    }
    return false;
  }

  return permute(verts.filter(v => v !== start), []);
}

console.log('Has Hamiltonian cycle:', hasHamiltonianCycle(g));
