// ── Tree verification + Bipartite check ───────────────────────

// Check if an adjacency Map represents a tree
function isTree(adjMap) {
  const vertices = [...adjMap.keys()];
  const n = vertices.length;
  // Count edges (each undirected edge appears in two lists)
  const totalDegree = vertices.reduce((s, v) => s + adjMap.get(v).length, 0);
  const edgeCount = totalDegree / 2;
  if (edgeCount !== n - 1) return false; // wrong edge count
  // BFS connectivity check
  const visited = new Set([vertices[0]]);
  const queue = [vertices[0]];
  while (queue.length) {
    const u = queue.shift();
    for (const { to: v } of adjMap.get(u)) {
      if (!visited.has(v)) { visited.add(v); queue.push(v); }
    }
  }
  return visited.size === n; // all vertices reachable
}

// ── Bipartite check via BFS 2-colouring ───────────────────────
function isBipartite(adjMap) {
  const colour = new Map();
  for (const start of adjMap.keys()) {
    if (colour.has(start)) continue; // already processed component
    colour.set(start, 0);
    const queue = [start];
    while (queue.length) {
      const u = queue.shift();
      const uColour = colour.get(u);
      for (const { to: v } of adjMap.get(u)) {
        if (!colour.has(v)) {
          colour.set(v, 1 - uColour); // flip colour
          queue.push(v);
        } else if (colour.get(v) === uColour) {
          return false; // same colour as neighbour → odd cycle
        }
      }
    }
  }
  return true;
}

// Build adjacency map for a tree (4 edges, 5 vertices)
const tree = new Map([
  ['A', [{to:'B'},{to:'C'}]],
  ['B', [{to:'A'},{to:'D'},{to:'E'}]],
  ['C', [{to:'A'}]],
  ['D', [{to:'B'}]],
  ['E', [{to:'B'}]]
]);

console.log('Is tree:', isTree(tree));         // true
console.log('Is bipartite:', isBipartite(tree)); // true — all trees are bipartite

// A triangle (odd cycle → not bipartite)
const triangle = new Map([
  ['X', [{to:'Y'},{to:'Z'}]],
  ['Y', [{to:'X'},{to:'Z'}]],
  ['Z', [{to:'X'},{to:'Y'}]]
]);
console.log('Triangle bipartite:', isBipartite(triangle)); // false
console.log('Triangle is tree:', isTree(triangle));        // false (3 edges, 3 vertices: 3 ≠ 2)
